"""Generates the tmux config that skins the harness in Aurelia colors and wires its keys and mouse."""
from __future__ import annotations

from atelier.theme import AURELIA as P

# $A is replaced by the absolute path of the atelier launcher.
_TEMPLATE = r"""
# generated by atelier - edits are overwritten on every launch
set -g default-terminal "tmux-256color"
set -as terminal-features ",*:RGB"
set -as terminal-features ",xterm*:extkeys"
set -g extended-keys on
set -g allow-passthrough on
set -g mouse on
set -g escape-time 10
set -g focus-events on
set -g history-limit 50000
set -g base-index 1
set -g pane-base-index 1
set -g renumber-windows on
set -g allow-rename off
set -g automatic-rename off
set -g set-clipboard on
set -g monitor-activity on
set -g visual-activity off
set -g prefix C-Space
bind C-Space send-prefix

# --- Aurelia skin ---
set -g status on
set -g status-position top
set -g status-interval 15
set -g status-style "bg=$BG,fg=$MUTED"
set -g status-left-length 40
set -g status-right-length 90
set -g status-left "#[fg=$ACCENT,bold] #{?client_prefix,#[fg=$RUN]◆,◆} atelier #[fg=$SURFACE]│#[default]#($A tick)"
set -g window-status-separator ""
set -g window-status-format "#[fg=$MUTED] #I #W#{?window_activity_flag,#[fg=$ACCENT]•,} "
set -g window-status-current-format "#[bg=$SURFACE,fg=$ACCENT,bold] #I #W #[default]"
set -g status-right "#[range=user|new]#[fg=$RUN]  + tab #[norange]#[range=user|sys]#[fg=$WEB] system #[norange]#[range=user|mgr]#[fg=$SEARCH] manage #[norange]#[fg=$MUTED]│ %H:%M "
set -g pane-border-style "fg=$SURFACE"
set -g pane-active-border-style "fg=$ACCENT"
set -g window-style "bg=$BG"
set -g window-active-style "bg=$BG"
set -g message-style "bg=$SURFACE,fg=$FG"
set -g message-command-style "bg=$SURFACE,fg=$ACCENT"
set -g mode-style "bg=$ACCENT,fg=$BG"
set -g popup-border-style "fg=$ACCENT"
set -g popup-style "bg=$BG"

# --- keys (F-keys and Alt+digits only: Claude Code keeps its own Ctrl and most Alt keys) ---
bind -n F1 select-window -t :=1
bind -n F2 run-shell "$A system"
bind -n F3 display-popup -E -w 72% -h 72% "$A panel pick"
bind -n F4 command-prompt -I "#W" "rename-window -- '%%'"
bind -n F5 run-shell "$A toggle tree"
bind -n F6 run-shell "$A toggle dash"
bind -n F7 display-popup -E -w 92% -h 88% "ccadmin"
bind -n F8 confirm-before -p "close tab #W? (y/n)" "run-shell '$A close #{window_id}'"
bind -n M-1 select-window -t :=1
bind -n M-2 select-window -t :=2
bind -n M-3 select-window -t :=3
bind -n M-4 select-window -t :=4
bind -n M-5 select-window -t :=5
bind -n M-6 select-window -t :=6
bind -n M-7 select-window -t :=7
bind -n M-8 select-window -t :=8
bind -n M-9 select-window -t :=9

# --- mouse on the tab bar: click a tab, double-click renames, the right-hand buttons act ---
bind -n MouseDown1Status if -F '#{==:#{mouse_status_range},new}' {
  display-popup -E -w 72% -h 72% "$A panel pick"
} {
  if -F '#{==:#{mouse_status_range},sys}' {
    run-shell "$A system"
  } {
    if -F '#{==:#{mouse_status_range},mgr}' {
      display-popup -E -w 92% -h 88% "ccadmin"
    } {
      select-window -t=
    }
  }
}
bind -n DoubleClick1Status command-prompt -I "#W" "rename-window -- '%%'"

# --- responsive panels and persistence ---
set-hook -g client-resized "run-shell -b '$A layout'"
set-hook -g client-attached "run-shell -b '$A layout'"
set-hook -g after-select-window "run-shell -b '$A layout'"
set-hook -g window-renamed "run-shell -b '$A save'"
set-hook -g after-new-window "run-shell -b '$A save'"
set-hook -g window-unlinked "run-shell -b '$A save'"
"""


def render(atelier_bin: str) -> str:
    out = _TEMPLATE
    colors = {
        "$BG": P.bg, "$SURFACE": P.surface, "$FG": P.fg, "$MUTED": P.muted, "$ACCENT": P.write,
        "$RUN": P.run, "$WEB": P.web, "$SEARCH": P.search,
    }
    for token in sorted(colors, key=len, reverse=True):
        out = out.replace(token, colors[token])
    return out.replace("$A", atelier_bin)  # last: "$A" is a prefix of "$ACCENT"
